import React, { useCallback, useState } from "react";

import { CourtList, MatchQueue, PlayerTable } from "./index";
import MoveMatchModal from "./components/MoveMatchModal"; // 👈 New import
import ReclubModal from "./components/ReclubModal";
import PartnersConfigModal from "./components/PartnersConfigModal";
import MatchProposalModal from "./components/MatchProposalModal";
import MatchProposalVersusModal from "./components/MatchProposalVersusModal";
import { SurfaceCard, ConfirmationModal } from "../../common/components";
import { useAppState } from "../../app/providers";
import {
  classifyPlayerPaymentBucket,
  isPlayerPaid,
  PAID_PAYMENT_BUCKETS,
} from "../../common/utils/paymentStatus";
import { DEFAULT_OPEN_PLAY_FEE } from "../../common/utils/settingsDefaults";
import { selectQueueState } from "../../state/selectors";

import toast from "react-hot-toast";
import { normalizeTeamsSettings } from "../../state/teamSettings";

export default function QueuePage() {
  const [reclubOpen, setReclubOpen] = useState(false);
  const [confirmCloseOpen, setConfirmCloseOpen] = useState(false);
  const [confirmCancelOpen, setConfirmCancelOpen] = useState(false);
  const [cancelReason, setCancelReason] = useState("");
  const [infoModal, setInfoModal] = useState({ isOpen: false, title: "", message: "" });
  const closeInfoModal = () => setInfoModal(prev => ({ ...prev, isOpen: false }));

  // New State for Move Match
  const [moveMatchModal, setMoveMatchModal] = useState({ isOpen: false, fromCourtId: null });
  // New State for Return to Queue
  const [returnCourtId, setReturnCourtId] = useState(null);
  const [partnersModalOpen, setPartnersModalOpen] = useState(false);
  const [proposalOpen, setProposalOpen] = useState(false);
  const [proposalData, setProposalData] = useState(null);
  const [proposalGenerating, setProposalGenerating] = useState(false);
  const [seenGroups, setSeenGroups] = useState([]);
  const [lastGenerateOptions, setLastGenerateOptions] = useState({});

  const extractGroupIds = useCallback((result) => {
    if (result?.groupIds?.length) return result.groupIds;
    if (result?.usedPlayers?.length === 4) return result.usedPlayers.map((p) => p.id);
    return [];
  }, []);

  const {
    courts,
    players,
    matchQueue,
    matches,
    currentOpSession,
    opSessions,
    importReclubParticipants,
    addCourt,
    removeCourt,
    clearExtraCourts,
    updateCourtName,
    addPlayer,
    updateGender,
    removePlayer,
    clearAllPlayers,
    assignPlayerToCourt,
    removePlayerFromCourt,
    stopPlayer,
    departPlayer,
    resumePlayer,
    previewAutoQueue,
    confirmAutoQueue,
    updateLevel,
    renamePlayer,
    addToQueue,
    addQueue,
    removeQueue,
    removeFromQueue,
    sendQueueToCourt,
    setCourtTeam,
    completeMatch,
    updateMatchDetails,
    updatePaymentStatus,
    updateMemberStatus,
    markPlayerArrived,
    markAllPaid,
    markAllArrived,
    startOpSession,
    closeOpSession,
    cancelOpSession,
    clearQueue,

    manualUnlockCourt,
    requestedMatches,
    addRequestedMatch,
    removeRequestedMatch,
    promoteRequestedMatchToQueue,
    moveMatch, // 👈 New
    returnToQueue, // 👈 New
    partners,
    addPartner,
    removePartner,
    togglePartner,
    settings,
    teams,
    setTeams,
    setTeamsModeEnabled,
    updateTeamsSettings,
    assignPlayerToTeam,
    removePlayerFromTeam,
    removeTeam,
    updateTeam,
  } = useAppState(selectQueueState);

  // New State for Start Session Confirmation
  const [confirmStartOpen, setConfirmStartOpen] = useState(false);
  const [sessionFeeInput, setSessionFeeInput] = useState(() =>
    String(settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE)
  );

  React.useEffect(() => {
    if (confirmStartOpen) {
      setSessionFeeInput(String(settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE));
    }
  }, [confirmStartOpen, settings?.defaultOpFee]);

  // Derive duplicate names reactively
  const duplicateNames = React.useMemo(() => {
    const counts = {};
    const dups = new Set();
    players.forEach(p => {
      const name = p.name.toUpperCase();
      counts[name] = (counts[name] || 0) + 1;
      if (counts[name] > 1) dups.add(name);
    });
    return Array.from(dups);
  }, [players]);

  const handleStartSession = () => {
    startOpSession(sessionFeeInput); // Pass custom fee
    setConfirmStartOpen(false);
    toast.success("Session started - Queue is now active");
  };

  const handleCompleteMatch = (courtId) => {
    completeMatch(courtId);
  };

  const handleReturnToQueue = (courtId) => {
    setReturnCourtId(courtId);
  };

  const confirmReturnToQueue = () => {
    if (returnCourtId) {
      returnToQueue(returnCourtId);
      toast.success("Returned players to Waiting List");
      setReturnCourtId(null);
    }
  };

  const handleRequestMove = (courtId) => {
    setMoveMatchModal({ isOpen: true, fromCourtId: courtId });
  };

  const renderPaymentSummary = () => {
    const summary = { cash: 0, gcash: 0, gotyme: 0, bank: 0, free: 0, notPaid: 0, members: 0, amount: 0 };
    const unpaid = [];
    (players || []).forEach((p) => {
      if (p.isMember) summary.members += 1;
      const bucket = classifyPlayerPaymentBucket(p.paymentStatus, p.paymentMethod);
      if (PAID_PAYMENT_BUCKETS.includes(bucket)) {
        summary[bucket] += 1;
        summary.amount += Number(p.price) || 0;
      } else if (bucket === "free") {
        summary.free += 1;
      } else {
        summary.notPaid += 1;
        unpaid.push(p);
      }
    });

    const total = PAID_PAYMENT_BUCKETS.reduce((sum, key) => sum + summary[key], 0) + summary.free + summary.notPaid;

    return (
      <div className="mb-4 grid grid-cols-1 sm:grid-cols-2 gap-3">
        <div className="border rounded-lg p-2 bg-slate-50">
          <h3 className="text-[11px] font-semibold text-slate-800 mb-1">Payment summary</h3>
          <ul className="space-y-0.5 text-[11px] text-slate-700">
            <li>Total players: {total}</li>
            <li>Members: {summary.members}</li>
            <li className="text-emerald-700">Paid (Cash): {summary.cash}</li>
            <li className="text-sky-700">Paid (GCash): {summary.gcash}</li>
            <li className="text-purple-700">Paid (GoTyme): {summary.gotyme}</li>
            <li className="text-teal-700">Paid (Bank): {summary.bank}</li>
            <li className="text-slate-700">Free / comped: {summary.free}</li>
            <li className="text-amber-600 font-medium">Unpaid: {summary.notPaid}</li>
            <li className="font-bold text-pt-teal">Collected: ₱{summary.amount.toLocaleString()}</li>
          </ul>
        </div>
        <div className="border rounded-lg p-2 bg-amber-50">
          <h3 className="text-[11px] font-semibold text-amber-800 mb-1">Unpaid players</h3>
          {unpaid.length === 0 ? (
            <p className="text-[11px] text-amber-600">All players are marked as paid or free.</p>
          ) : (
            <ul className="max-h-32 overflow-auto text-[11px] text-amber-900 list-disc list-inside">
              {unpaid.map((p) => (
                <li key={p.id}>{p.name}</li>
              ))}
            </ul>
          )}
          <p className="mt-1 text-[10px] text-amber-800">
            Make sure this list matches your cashier records before ending the session.
          </p>
        </div>
      </div>
    );
  };

  const handleAutoBuild = useCallback((options = {}) => {
    const excludeIds = requestedMatches.flatMap((m) => m.playerIds);
    const result = previewAutoQueue({ excludeIds, partners, ...options });
    const shownGroupIds = extractGroupIds(result);

    if (shownGroupIds.length > 0) setSeenGroups([shownGroupIds]);
    else setSeenGroups([]);

    setLastGenerateOptions({ excludeIds, partners, ...options });
    setProposalData(result);
    setProposalOpen(true);
  }, [previewAutoQueue, requestedMatches, partners, extractGroupIds]);

  const handleReGenerate = useCallback(() => {
    setProposalGenerating(true);
    setTimeout(() => {
      const excludeIds = requestedMatches.flatMap((m) => m.playerIds);
      const excludeGroups = seenGroups.map((ids) => ids.map(String).sort());
      const result = previewAutoQueue({
        ...lastGenerateOptions,
        excludeIds,
        partners,
        excludeGroups,
      });
      const shownGroupIds = extractGroupIds(result);
      if (shownGroupIds.length > 0) {
        setSeenGroups((prev) => [...prev, shownGroupIds]);
      }
      setProposalData(result);
      setProposalGenerating(false);
    }, 300);
  }, [previewAutoQueue, lastGenerateOptions, requestedMatches, partners, seenGroups, extractGroupIds]);

  const handleConfirmProposal = useCallback(() => {
    if (!proposalData?.groupIds?.length) return;
    confirmAutoQueue({
      groupIds: proposalData.groupIds,
      reason: proposalData.reason || "Auto",
      teamMeta: proposalData.teamMeta || null,
    });
    setProposalOpen(false);
    setProposalData(null);
    setSeenGroups([]);
    toast.success("Match queued!");
  }, [proposalData, confirmAutoQueue]);

  const teamsSettingsNorm = React.useMemo(
    () => normalizeTeamsSettings(settings?.teams),
    [settings?.teams]
  );

  return (
    <div className="p-4 w-full h-full flex flex-col overflow-hidden admin-page-bg">
      <div className="flex items-center justify-between mb-4">
        {/* ── Session Stats ── */}
        {(() => {
          const LEVELS = [
            { key: 'Newbie', label: 'Newbie', color: '#94A3B8', text: '#fff' },
            { key: 'Beginner', label: 'Beginner', color: '#F59E0B', text: '#fff' },
            { key: 'L.Inter', label: 'Low Inter', color: '#22C55E', text: '#fff' },
            { key: 'H.Inter', label: 'High Inter', color: '#3B82F6', text: '#fff' },
            { key: 'Advance', label: 'Advance', color: '#8B5CF6', text: '#fff' },
          ];
          const total = players.length;
          const arrived = players.filter(p => p.arrivalTime).length;
          const paid = players.filter((p) => isPlayerPaid(p.paymentStatus, p.paymentMethod)).length;
          const completedMatches = matches.filter(m => m.status === 'completed').length;
          const hasStats = total > 0 || completedMatches > 0;
          if (!hasStats) return <h1 className="text-2xl page-title">Queue</h1>;
          return (
            <div className="flex flex-col gap-1.5">
              {/* Level pills row */}
              <div className="flex items-center gap-1.5 flex-wrap">
                {LEVELS.map(({ key, label, color, text }) => {
                  const count = players.filter(p => p.level === key).length;
                  if (count === 0) return null;
                  return (
                    <span key={key}
                      className="inline-flex items-center gap-1.5 px-2.5 py-0.5 rounded-md text-[11px] font-semibold"
                      style={{ background: `${color}18`, color: color, border: `1px solid ${color}40` }}>
                      <span className="w-1.5 h-1.5 rounded-full inline-block shrink-0" style={{ background: color }} />
                      {label} · {count}
                    </span>
                  );
                })}
              </div>
              {/* Summary row */}
              {total > 0 && (
                <div className="flex items-center gap-4 text-[11px] text-slate-500 font-medium">
                  <span className="flex items-center gap-1">
                    <span className="text-emerald-500 font-bold">{arrived}</span>
                    <span>/ {total} Arrived</span>
                  </span>
                  <span className="text-slate-300">·</span>
                  <span className="flex items-center gap-1">
                    <span className="text-blue-500 font-bold">{paid}</span>
                    <span>/ {total} Paid</span>
                  </span>
                  {completedMatches > 0 && (
                    <>
                      <span className="text-slate-300">·</span>
                      <span className="flex items-center gap-1">
                        <span className="text-pt-teal font-bold">{completedMatches}</span>
                        <span>Matches</span>
                      </span>
                    </>
                  )}
                </div>
              )}
            </div>
          );
        })()}
        <div className="flex items-center gap-3">
          <div className="flex flex-col items-end mr-2 text-xs text-pt-navy/50">
            <span className="font-medium">
              {currentOpSession ? currentOpSession.name : "No active OP session"}
            </span>
            {currentOpSession ? (
              <span>
                Started {new Date(currentOpSession.startedAt).toLocaleTimeString()}
              </span>
            ) : (
              <span>
                {opSessions.length} past session{opSessions.length === 1 ? "" : "s"}
              </span>
            )}
            {!currentOpSession && (
              <span className="inline-flex items-center gap-1 mt-1 text-[11px] text-amber-900 bg-amber-100 px-2 py-0.5 rounded-full border border-amber-200">
                <span className="w-1.5 h-1.5 rounded-full bg-amber-600" />
                Queue locked until a session is started
              </span>
            )}
          </div>
          {currentOpSession ? (
            <div className="flex items-center gap-2">
              <button
                onClick={() => setConfirmCloseOpen(true)}
                className="px-4 py-2 rounded-full text-xs font-medium bg-red-600 text-white hover:bg-red-700 shadow-sm transition-colors"
              >
                Close Session
              </button>
              <button
                onClick={() => setConfirmCancelOpen(true)}
                className="px-4 py-2 rounded-full text-xs font-medium bg-amber-600 text-white hover:bg-amber-600 shadow-sm transition-colors"
              >
                Cancel Session
              </button>
            </div>
          ) : (
            <button
              onClick={() => {
                if (currentOpSession) return;
                setConfirmStartOpen(true);
              }}
              className="px-4 py-2 rounded-full text-xs font-medium bg-pt-teal text-white hover:bg-pt-teal/90 shadow-sm transition-transform active:scale-95"
            >
              Start Session
            </button>
          )}
          <button
            onClick={() => window.open(window.location.href.split('#')[0] + "#/display", "dink_display", "width=1280,height=720")}
            className="text-sm text-pt-teal font-medium underline decoration-pt-green/30 hover:decoration-pt-green transition-all ml-2"
          >
            Open Display
          </button>
        </div>
      </div>

      <div className="mt-2 grid grid-cols-1 md:grid-cols-12 gap-4 flex-1 min-h-0 overflow-x-hidden relative">
        {/* BLOCKER OVERLAY */}
        {!currentOpSession && (
          <div className="absolute inset-0 z-50 bg-white/60 backdrop-blur-[2px] flex flex-col items-center justify-center rounded-xl border border-dashed border-slate-300">
            <div className="bg-white p-6 rounded-2xl shadow-xl flex flex-col items-center text-center max-w-sm border border-slate-100">
              <div className="w-12 h-12 rounded-full bg-pt-teal/10 flex items-center justify-center mb-4 text-2xl text-pt-teal">
                🔒
              </div>
              <h3 className="text-lg font-display text-slate-800 mb-2">Queue System Locked</h3>
              <p className="text-xs text-slate-500 mb-6 leading-relaxed">
                Please start an Open Play Session to manage players, courts, and matches. This ensures all your stats are tracked correctly.
              </p>
              <button
                onClick={() => setConfirmStartOpen(true)}
                className="bg-pt-teal text-white px-6 py-2.5 rounded-full text-sm font-medium hover:bg-pt-teal/90 shadow-lg shadow-pt-teal/20 hover:scale-[1.02] transition-all"
              >
                Start New Session
              </button>
            </div>
          </div>
        )}

        <div className="md:col-span-6 flex flex-col min-h-0 overflow-x-hidden">
          <SurfaceCard className="flex-1 min-h-0 pr-1 border-pt-teal/10 shadow-sm" padded={false} bodyClassName="h-full p-3 bg-white/70 backdrop-blur-sm">
            <PlayerTable
              players={players}
              matches={matches}
              currentOpSession={currentOpSession}
              onAddPlayer={addPlayer}
              onRemovePlayer={removePlayer}
              onUpdateLevel={updateLevel}
              onStopPlayer={stopPlayer}
              onDepartPlayer={departPlayer}
              onResumePlayer={resumePlayer}
              onUpdateGender={updateGender}
              onUpdatePaymentStatus={updatePaymentStatus}
              onUpdateMemberStatus={updateMemberStatus}
              onMarkArrived={markPlayerArrived}
              onMarkAllPaid={markAllPaid}
              onMarkAllArrived={markAllArrived}
              disabled={!currentOpSession}
              matchQueue={matchQueue}
              onAddToQueue={addToQueue}
              onRenamePlayer={renamePlayer}
              onOpenReclub={() => setReclubOpen(true)}
              onUpdateMatch={updateMatchDetails}
              duplicateNames={duplicateNames}
              requestedMatches={requestedMatches}
              partners={partners}
              teamsModeEnabled={settings?.teamsModeEnabled}
              teams={teams}
              settings={settings}
              setTeamsModeEnabled={setTeamsModeEnabled}
              updateTeamsSettings={updateTeamsSettings}
              setTeams={setTeams}
              assignPlayerToTeam={assignPlayerToTeam}
              removePlayerFromTeam={removePlayerFromTeam}
              removeTeam={removeTeam}
              updateTeam={updateTeam}
            />
          </SurfaceCard>
        </div>

        <div className="md:col-span-3 flex flex-col min-h-0 overflow-x-hidden">
          <SurfaceCard padded={false} bodyClassName="flex-1 overflow-hidden p-3 bg-white/70 backdrop-blur-sm" className="border-pt-teal/10 shadow-sm h-full flex flex-col overflow-hidden">
            <MatchQueue
              players={players}
              courts={courts}
              queue={matchQueue}
              requestedMatches={requestedMatches}
              onAddRequestedMatch={addRequestedMatch}
              onRemoveRequestedMatch={removeRequestedMatch}
              onPromoteRequestedMatch={promoteRequestedMatchToQueue}
              onAddQueue={addQueue}
              onRemoveQueue={removeQueue}
              onRemoveFromQueue={removeFromQueue}
              onSendQueueToCourt={sendQueueToCourt}
              onAutoBuild={handleAutoBuild}
              compact
              disabled={!currentOpSession}
              partners={partners}
              onOpenPartners={() => setPartnersModalOpen(true)}
              teamsModeEnabled={settings?.teamsModeEnabled}
              teams={teams}
              teamsSettings={normalizeTeamsSettings(settings?.teams)}
            />
          </SurfaceCard>
        </div>

        <div className="md:col-span-3 flex flex-col min-h-0 overflow-x-hidden">
          <div className="mb-2 flex gap-2 justify-end">
            <button
              onClick={() => {
                const bc = new BroadcastChannel("dink_manager");
                bc.postMessage({ type: "CLOSE_MODAL" });
                bc.close();
                toast.success("Display modals closed");
              }}
              className="px-4 py-2 rounded-full text-xs font-medium bg-amber-600 text-white hover:bg-amber-600 shadow-sm transition-colors"
              title="Force close any open modals on the Display Screen"
            >
              Close Modal
            </button>

            <button
              onClick={addCourt}
              className="bg-pt-teal text-white px-4 py-2 rounded-full text-xs font-medium hover:bg-pt-teal/90 transition-colors shadow-sm"
            >
              + Add Court
            </button>
            <button
              onClick={clearExtraCourts}
              className="border border-pt-teal text-pt-teal px-4 py-2 rounded-full text-xs font-medium hover:bg-pt-teal/10 transition-colors"
            >
              Clear Extras
            </button>
          </div>
          <SurfaceCard padded={false} bodyClassName="flex-1 overflow-y-auto p-3 bg-transparent shadow-none" className="bg-transparent shadow-none border-none">
            <CourtList
              courts={courts}
              players={players}
              matches={matches}
              teamsModeEnabled={settings?.teamsModeEnabled}
              teams={teams}
              teamsSettings={normalizeTeamsSettings(settings?.teams)}
              onAssign={assignPlayerToCourt}
              onRemove={removePlayerFromCourt}
              onUnlockCourt={manualUnlockCourt}
              onRemoveCourt={removeCourt}
              onUpdateCourtName={updateCourtName}
              onSetTeams={setCourtTeam}
              onCompleteMatch={handleCompleteMatch}
              noTopMargin
              className="grid grid-cols-1 gap-3"
              compact
              onRequestMove={handleRequestMove}
              onReturnToQueue={handleReturnToQueue}
            />
          </SurfaceCard>
        </div>
      </div>

      <footer className="text-center text-pt-teal/40 text-[10px] mt-4 font-mono">
        POWERED BY <span className="font-bold text-pt-teal/60">DINK MANAGER</span>
      </footer>

      <ReclubModal
        open={reclubOpen}
        onClose={() => setReclubOpen(false)}
        onImportParticipants={(payload) => {
          importReclubParticipants(payload);
          setReclubOpen(false);
        }}
      />

      <PartnersConfigModal
        isOpen={partnersModalOpen}
        onClose={() => setPartnersModalOpen(false)}
        players={players}
        partners={partners}
        onAddPartner={addPartner}
        onRemovePartner={removePartner}
        onTogglePartner={togglePartner}
      />

      {!!returnCourtId && (
        <ConfirmationModal
          isOpen={!!returnCourtId}
          onCancel={() => setReturnCourtId(null)}
          onConfirm={confirmReturnToQueue}
          title="Return Match to Queue"
          message="Are you sure you want to put this match back in the queue? Active wait time for these players will be restored."
          confirmLabel="Yes, Return to Queue"
          cancelLabel="Cancel"
          isDestructive={false}
        />
      )}

      <MoveMatchModal
        isOpen={moveMatchModal.isOpen}
        onClose={() => setMoveMatchModal({ isOpen: false, fromCourtId: null })}
        fromCourtName={courts.find(c => c.id === moveMatchModal.fromCourtId)?.name}
        courts={courts}
        onMove={(targetId) => {
          moveMatch(moveMatchModal.fromCourtId, targetId);
          setMoveMatchModal({ isOpen: false, fromCourtId: null });
        }}
      />

      {confirmCloseOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full mx-4 p-6 text-xs border border-pt-teal/10">
            <h2 className="text-lg font-display text-pt-teal mb-2">
              Review payments before ending session
            </h2>
            <p className="text-xs text-gray-600 mb-4 font-body">
              This will save a snapshot of the current Open Play session and clear players, queue, and courts.
              Please review payment statuses first.
            </p>
            {renderPaymentSummary()}
            <div className="flex flex-col sm:flex-row gap-2 justify-end mt-4">

              <button
                type="button"
                onClick={() => {
                  closeOpSession();
                  clearQueue();
                  clearAllPlayers();
                  setConfirmCloseOpen(false);
                }}
                className="bg-red-600 text-white px-4 py-2 rounded-full text-xs font-medium hover:bg-red-700"
              >
                Close and Clear
              </button>
              <button
                type="button"
                onClick={() => setConfirmCloseOpen(false)}
                className="border border-slate-200 text-slate-600 px-4 py-2 rounded-full text-xs font-medium hover:bg-slate-50"
              >
                Cancel
              </button>
            </div>
          </div>
        </div>
      )}

      {confirmCancelOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/30 backdrop-blur-sm">
          <div className="bg-white rounded-xl shadow-xl max-w-lg w-full mx-4 p-6 text-xs border border-pt-teal/10">
            <h2 className="text-lg font-display text-pt-teal mb-2">Cancel current session</h2>
            <p className="text-xs text-gray-600 mb-4">
              This will delete the in-progress session without saving a summary.
            </p>
            <label className="block text-xs font-bold text-gray-800 mb-1 uppercase tracking-wide">
              Optional reason
            </label>
            <textarea
              rows="3"
              className="w-full border border-slate-200 rounded-lg p-2 text-xs focus:ring-pt-green focus:border-pt-teal"
              placeholder="e.g. Rain delay, power outage"
              value={cancelReason}
              onChange={(e) => setCancelReason(e.target.value)}
            />
            <div className="flex flex-col sm:flex-row gap-2 justify-end mt-4">
              <button
                type="button"
                onClick={() => {
                  cancelOpSession(cancelReason.trim() || undefined);
                  clearQueue();
                  clearAllPlayers();
                  setCancelReason("");
                  setConfirmCancelOpen(false);
                }}
                className="bg-amber-600 text-white px-4 py-2 text-xs font-medium rounded-full hover:bg-amber-600 transition-colors"
              >
                Delete Session
              </button>
              <button
                type="button"
                onClick={() => {
                  setCancelReason("");
                  setConfirmCancelOpen(false);
                }}
                className="border border-slate-200 text-slate-600 px-4 py-2 text-xs font-medium rounded-full hover:bg-slate-50"
              >
                Keep Session
              </button>
            </div>
          </div>
        </div>
      )}

      {/* START SESSION CONFIRMATION MODAL */}
      {confirmStartOpen && (
        <div className="fixed inset-0 z-50 flex items-center justify-center bg-black/40 backdrop-blur-sm animate-in fade-in duration-200">
          <div className="bg-white rounded-xl shadow-2xl max-w-sm w-full mx-4 p-6 border border-pt-teal/20">
            <h2 className="text-xl font-display text-pt-teal mb-2">Start Open Play Session</h2>
            <p className="text-sm text-slate-600 mb-4">
              Starting a new session will reset the queue and court status. Previous session data will be saved to history.
            </p>

            <div className="mb-6">
              <label className="block text-xs font-bold text-slate-700 mb-1 uppercase tracking-wider">
                Session Fee (PHP)
              </label>
              <div className="relative">
                <span className="absolute left-3 top-1/2 -translate-y-1/2 text-slate-400 font-medium">₱</span>
                <input
                  type="number"
                  value={sessionFeeInput}
                  onChange={(e) => setSessionFeeInput(e.target.value)}
                  className="w-full pl-7 pr-4 py-2 border border-slate-300 rounded-lg focus:ring-2 focus:ring-pt-green focus:border-pt-teal outline-none font-medium text-slate-900"
                  placeholder={String(settings?.defaultOpFee ?? DEFAULT_OPEN_PLAY_FEE)}
                />
              </div>
              <p className="text-[10px] text-slate-400 mt-1">
                This fee will be applied to all players in this session.
              </p>
            </div>

            <div className="flex justify-end gap-3">
              <button
                onClick={() => setConfirmStartOpen(false)}
                className="px-4 py-2 text-sm font-medium text-slate-600 hover:bg-slate-100 rounded-lg transition-colors"
              >
                Cancel
              </button>
              <button
                onClick={handleStartSession}
                className="px-6 py-2 text-sm font-bold text-white bg-pt-teal hover:bg-pt-teal/90 rounded-lg shadow-sm transition-transform active:scale-95"
              >
                Start Session
              </button>
            </div>
          </div>
        </div>
      )}

      <ConfirmationModal
        isOpen={infoModal.isOpen}
        title={infoModal.title}
        message={infoModal.message}
        confirmLabel="OK"
        cancelLabel={null} // Single button mode
        onConfirm={closeInfoModal}
        onCancel={closeInfoModal}
      />

      {proposalData?.mode === "teams" ? (
        <MatchProposalVersusModal
          isOpen={proposalOpen}
          proposal={proposalData}
          showDisclaimer={teamsSettingsNorm.showVersusDisclaimer !== false}
          onConfirm={handleConfirmProposal}
          onReGenerate={handleReGenerate}
          onClose={() => {
            setProposalOpen(false);
            setProposalData(null);
            setSeenGroups([]);
          }}
          isRegenerating={proposalGenerating}
        />
      ) : (
        <MatchProposalModal
          isOpen={proposalOpen}
          proposal={proposalData}
          partners={partners}
          teamsModeEnabled={settings?.teamsModeEnabled}
          teams={teams}
          teamsSettings={teamsSettingsNorm}
          onConfirm={handleConfirmProposal}
          onReGenerate={handleReGenerate}
          onClose={() => {
            setProposalOpen(false);
            setProposalData(null);
            setSeenGroups([]);
          }}
          isRegenerating={proposalGenerating}
        />
      )}
    </div>
  );
}
