import { FACILITY_ID, apiRequest } from "./client";

export function fetchFacilitySettings() {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/settings`, {
    fallbackError: "Could not load settings",
  });
}

export function fetchInvoiceSettings() {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/invoice`, {
    fallbackError: "Could not load GCash settings",
  });
}

export function saveFacilitySettings(calendarSettings) {
  return apiRequest(`/api/v1/facilities/${FACILITY_ID}/settings`, {
    method: "PUT",
    body: { calendar_settings: calendarSettings },
    fallbackError: "Could not save settings",
  });
}
