import React from "react";
import { Link } from "react-router-dom";
import SurfaceCard from "../../../common/components/SurfaceCard";
import { formatMinutesAmpm } from "../../calendar/v2/calendarUtils";
import { isRentalBooking } from "../../../common/utils/reportPrimitives";
import { getRentalBookingFinancials } from "../../../common/utils/pricing";

export default function TodayBoard({
  localYMD,
  todayRentals = [],
  currentOpSession,
  livePlayerCount = 0,
  liveUnpaidCount = 0,
  onOpenBooking,
  formatCurrency,
}) {
  const todayLabel = new Date().toLocaleDateString(undefined, {
    weekday: "long",
    month: "short",
    day: "numeric",
  });

  return (
    <SurfaceCard
      title="Today (operations)"
      description={todayLabel}
      actions={
        <div className="flex gap-3 text-xs font-semibold">
          <Link to="/queue" className="text-pt-teal hover:text-pt-navy">
            Open Queue
          </Link>
          <Link to="/calendar-v2" className="text-pt-teal hover:text-pt-navy">
            Open Calendar
          </Link>
        </div>
      }
      className="mb-8"
      accent
    >
      {currentOpSession && String(currentOpSession.status).toLowerCase() === "active" && (
        <div className="mb-4 p-3 rounded-lg bg-emerald-50 border border-emerald-100 flex flex-wrap items-center justify-between gap-2">
          <div>
            <p className="text-xs font-bold uppercase text-emerald-800 tracking-wide">Live Open Play</p>
            <p className="text-sm text-emerald-900 font-medium">
              {currentOpSession.name || "Active session"} · {livePlayerCount} player
              {livePlayerCount === 1 ? "" : "s"}
              {liveUnpaidCount > 0 ? ` · ${liveUnpaidCount} unpaid` : ""}
            </p>
          </div>
          <Link
            to="/queue"
            className="text-xs font-bold text-emerald-800 bg-white px-3 py-1.5 rounded-lg border border-emerald-200 hover:bg-emerald-100"
          >
            Go to Queue
          </Link>
        </div>
      )}

      {!currentOpSession && (
        <p className="text-xs text-slate-400 mb-3">No live Open Play session right now.</p>
      )}

      <h4 className="section-label mb-3">Today&apos;s Rentals</h4>
      <div className="admin-card overflow-hidden max-h-[360px] overflow-y-auto">
        {todayRentals.length === 0 ? (
          <div className="p-8 text-center text-slate-400 text-sm">No rentals scheduled for today.</div>
        ) : (
          <table className="w-full text-left text-xs">
            <thead className="bg-slate-50 border-b border-slate-100 text-slate-500 font-semibold sticky top-0">
              <tr>
                <th className="py-3 px-4">Time</th>
                <th className="py-3 px-4">Booking / Renter</th>
                <th className="py-3 px-4">Courts</th>
                <th className="py-3 px-4 text-right">Payment</th>
              </tr>
            </thead>
            <tbody className="divide-y divide-slate-100">
              {todayRentals.map((g) => {
                let badgeClass = "bg-amber-50 text-amber-700 border-amber-200";
                if (g.paymentStatus === "paid") badgeClass = "bg-emerald-50 text-emerald-700 border-emerald-200";
                if (g.paymentStatus === "partial") badgeClass = "bg-blue-50 text-blue-700 border-blue-200";

                return (
                  <tr
                    key={g.id}
                    className="hover:bg-slate-50 transition-colors cursor-pointer"
                    onClick={() => onOpenBooking(g.id)}
                  >
                    <td className="py-3 px-4 font-mono text-slate-600 whitespace-nowrap">
                      {g.startLabel} - {g.endLabel}
                    </td>
                    <td className="py-3 px-4 min-w-[200px]">
                      <div className="font-semibold text-slate-900 text-sm">{g.title || "Rental"}</div>
                      <div className="text-[11px] text-slate-500">{g.renterName}</div>
                    </td>
                    <td className="py-3 px-4 text-slate-600 whitespace-nowrap">{g.courtIds}</td>
                    <td className="py-3 px-4 text-right">
                      <span className={`inline-flex items-center px-2 py-0.5 rounded text-[10px] font-bold uppercase border ${badgeClass}`}>
                        {g.paymentStatus}
                      </span>
                      {g.outstandingBalance > 0 && (
                        <div className="text-[10px] text-rose-600 mt-0.5">
                          Bal {formatCurrency(g.outstandingBalance)}
                        </div>
                      )}
                    </td>
                  </tr>
                );
              })}
            </tbody>
          </table>
        )}
      </div>
    </SurfaceCard>
  );
}

/** Build grouped today rental rows from slots/bookings maps. */
export function buildTodayRentals(bookingsV2, slotsV2, localYMD) {
  const todaySlots = Object.values(slotsV2 || {}).filter((s) => {
    if (!s || s.status === "CANCELLED") return false;
    if (s.date && s.date === localYMD) return true;
    return false;
  });

  const groups = {};
  todaySlots.forEach((slot) => {
    const b = bookingsV2[slot.bookingId];
    if (!isRentalBooking(b)) return;
    if (!groups[b.id]) {
      groups[b.id] = {
        id: b.id,
        title: b.title,
        renterName: b.renter?.name || "Pickle Renter",
        courtIds: new Set(),
        slots: [],
      };
    }
    groups[b.id].courtIds.add(slot.courtId);
    groups[b.id].slots.push(slot);
  });

  return Object.values(groups)
    .map((g) => {
      const booking = bookingsV2[g.id];
      const { balance, paymentStatus } = getRentalBookingFinancials(booking, slotsV2);
      g.slots.sort((a, b) => a.startTime - b.startTime);
      const start = g.slots[0];
      const end = g.slots[g.slots.length - 1];
      let pay = "unpaid";
      if (paymentStatus === "PAID") pay = "paid";
      else if (paymentStatus === "PARTIAL") pay = "partial";
      else if (paymentStatus === "FREE") pay = "free";
      return {
        ...g,
        courtIds: Array.from(g.courtIds).sort().join(", "),
        startLabel: formatMinutesAmpm(start.startTime),
        endLabel: formatMinutesAmpm(end.endTime),
        paymentStatus: pay,
        outstandingBalance: balance,
      };
    })
    .sort((a, b) => a.slots[0].startTime - b.slots[0].startTime);
}
