// Simple Web Speech API helper with voice selection + tuning
export function getVoicesSafe() {
  const v = window.speechSynthesis?.getVoices?.() || [];
  // Sort: natural-sounding names first if present
  return v.sort((a, b) => (a.name || "").localeCompare(b.name || ""));
}

export function speak(text, { voiceName, rate = 0.9, pitch = 1.0, lang } = {}) {
  if (!("speechSynthesis" in window)) return;
  const u = new SpeechSynthesisUtterance(text);
  const all = getVoicesSafe();

  if (voiceName) {
    const chosen = all.find(v => v.name === voiceName);
    if (chosen) u.voice = chosen;
  }
  if (lang) u.lang = lang;
  u.rate = rate;   // 0.7–1.0 often sounds more natural
  u.pitch = pitch; // 0.9–1.1 keeps it from sounding chipmunky
  window.speechSynthesis.cancel(); // stop any ongoing speech
  window.speechSynthesis.speak(u);
}
