import React, { useEffect } from "react";
import { createPortal } from "react-dom";
import { X } from "lucide-react";
import TeamBadge, { resolveTeamBadgeDisplay } from "./TeamBadge";

const LEVEL_COLORS = {
  Newbie: "#94A3B8",
  Beginner: "#F59E0B",
  "L.Inter": "#22C55E",
  "H.Inter": "#3B82F6",
  Advance: "#8B5CF6",
  Intermediate: "#3B82F6",
};

function MatchCard({
  item,
  players,
  courts,
  teamsModeEnabled,
  teams,
  teamsSettings,
  onSendQueueToCourt,
  onRemoveQueue,
  onRemoveFromQueue,
  readOnly,
}) {
  const team = (item.playerIds || [])
    .map((id) => players.find((p) => p.id === id))
    .filter(Boolean);

  const queuedAt = item.createdAt
    ? new Date(item.createdAt).toLocaleTimeString([], { hour: "numeric", minute: "2-digit" })
    : "—";

  return (
    <div className="border border-pt-teal/15 rounded-xl p-4 bg-white shadow-sm">
      <div className="mb-3">
        <p className="text-[10px] font-bold uppercase tracking-widest text-pt-teal/70">Queued match</p>
        <p className="text-xs text-slate-500 mt-0.5">{queuedAt} · {item.reason || "Manual"}</p>
      </div>

      <ul className="grid grid-cols-2 gap-2">
        {team.map((p) => {
          const tb = resolveTeamBadgeDisplay(
            p,
            item.teamMeta,
            teamsModeEnabled,
            teams,
            teamsSettings?.unassignedLabel
          );
          return (
            <li
              key={p.id}
              className={`flex items-center gap-2 rounded-lg px-2.5 py-2 border text-sm ${
                p.gender === "F" ? "bg-pink-50 border-pink-100" : "bg-slate-50 border-slate-100"
              }`}
            >
              {tb ? (
                <TeamBadge letter={tb.letter} color={tb.color} title={tb.title} />
              ) : (
                <span
                  className="w-6 h-6 rounded-full shrink-0 inline-flex items-center justify-center text-white font-black text-[10px]"
                  style={{ backgroundColor: LEVEL_COLORS[p.level] || "#94A3B8" }}
                >
                  {(p.level || "L").charAt(0)}
                </span>
              )}
              <div className="min-w-0 flex-1">
                <p className="font-semibold text-slate-800 truncate">{p.name}</p>
                <p className="text-[10px] text-slate-500">
                  {p.level} · {p.gender === "F" ? "F" : "M"} · {p.matches} matches
                </p>
              </div>
              {!readOnly && onRemoveFromQueue && (
                <button
                  type="button"
                  className="text-red-400 hover:text-red-600 text-sm shrink-0 px-1"
                  title={`Remove ${p.name} from queue`}
                  onClick={() => onRemoveFromQueue(item.id, p.id)}
                >
                  ×
                </button>
              )}
            </li>
          );
        })}
      </ul>

      {!readOnly && (
        <div className="flex flex-wrap gap-2 mt-3 pt-3 border-t border-slate-100">
          <button
            type="button"
            className="text-xs font-bold px-3 py-1.5 rounded-lg bg-pt-teal text-white hover:bg-pt-teal/90"
            onClick={() => onSendQueueToCourt?.(item.id, null)}
          >
            Send to court
          </button>
          <select
            className="text-xs border border-slate-200 rounded-lg px-2 py-1.5 bg-white"
            defaultValue=""
            onChange={(e) => {
              const cid = Number(e.target.value);
              if (cid) onSendQueueToCourt?.(item.id, cid);
              e.target.value = "";
            }}
          >
            <option value="">Pick court…</option>
            {courts.map((c) => (
              <option key={c.id} value={c.id}>
                {c.name} ({4 - (c.players?.length || 0)} free)
              </option>
            ))}
          </select>
          <button
            type="button"
            className="text-xs font-bold text-red-600 hover:bg-red-50 px-2 py-1.5 rounded-lg ml-auto"
            onClick={() => onRemoveQueue?.(item.id)}
          >
            Remove
          </button>
        </div>
      )}
    </div>
  );
}

export default function QueueExpandModal({
  isOpen,
  onClose,
  queue = [],
  players = [],
  courts = [],
  teamsModeEnabled = false,
  teams = [],
  teamsSettings = {},
  onSendQueueToCourt,
  onRemoveQueue,
  onRemoveFromQueue,
  readOnly = false,
}) {
  useEffect(() => {
    if (!isOpen) return undefined;
    const onKey = (e) => {
      if (e.key === "Escape") onClose?.();
    };
    window.addEventListener("keydown", onKey);
    return () => window.removeEventListener("keydown", onKey);
  }, [isOpen, onClose]);

  if (!isOpen) return null;

  return createPortal(
    <div
      className="fixed inset-0 z-[200] flex items-center justify-center bg-black/40 backdrop-blur-sm p-4"
      onClick={onClose}
      role="dialog"
      aria-modal="true"
      aria-labelledby="queue-expand-title"
    >
      <div
        className="bg-slate-50 rounded-2xl shadow-2xl w-full max-w-4xl max-h-[90vh] flex flex-col overflow-hidden"
        onClick={(e) => e.stopPropagation()}
      >
        <div className="flex items-center justify-between px-6 py-4 border-b border-slate-200 bg-white">
          <div>
            <h2 id="queue-expand-title" className="text-lg font-bold text-slate-900">Match queue</h2>
            <p className="text-sm text-slate-500">{queue.length} match{queue.length !== 1 ? "es" : ""} waiting</p>
          </div>
          <button
            type="button"
            onClick={onClose}
            className="p-2 rounded-full text-slate-400 hover:bg-slate-100 hover:text-slate-700"
          >
            <X className="h-5 w-5" />
          </button>
        </div>

        <div className="flex-1 overflow-y-auto p-6">
          {queue.length === 0 ? (
            <p className="text-center text-slate-400 py-12">No queued matches.</p>
          ) : (
            <div className="grid grid-cols-1 md:grid-cols-2 gap-4">
              {queue.map((item) => (
                <MatchCard
                  key={item.id}
                  item={item}
                  players={players}
                  courts={courts}
                  teamsModeEnabled={teamsModeEnabled}
                  teams={teams}
                  teamsSettings={teamsSettings}
                  onSendQueueToCourt={onSendQueueToCourt}
                  onRemoveQueue={onRemoveQueue}
                  onRemoveFromQueue={onRemoveFromQueue}
                  readOnly={readOnly}
                />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>,
    document.body
  );
}
