import config from "../../config";

export const DEFAULT_OPEN_PLAY_FEE = config.pricing?.openPlayRate ?? 200;
export const DEFAULT_RENTAL_RATE = config.pricing?.rentalRate ?? 300;
export const DEFAULT_MEMBER_DISCOUNT = config.pricing?.memberDiscount ?? 30;
export const DEFAULT_PICKLECAM_FEE = config.pricing?.pickleCamFee ?? 25;
export const DEFAULT_BALL_FEE = config.pricing?.ballFee ?? 78;
export const DEFAULT_CALENDAR_OPEN_HOUR = config.calendar?.openHour ?? 8;
export const DEFAULT_CALENDAR_CLOSE_HOUR = config.calendar?.closeHour ?? 24;
export const DEFAULT_MASTER_PASSWORD =
  config.masterPassword || "picklechilladmin";

/** One-time migration key: PickleCam switched from a flat booking fee to hourly. */
export const PICKLECAM_HOURLY_RATE_MIGRATION = "pickleCamHourlyRateV1";

/** Apply one-time persisted settings migrations after loadState(). */
export const applyPersistedStateMigrations = (state) => {
  if (!state) return null;

  const migrations = { ...(state.meta?.migrations || {}) };
  if (migrations[PICKLECAM_HOURLY_RATE_MIGRATION]) {
    return state;
  }

  // Mark hourly mode as applied, but do not overwrite pickleCamFee. Calendar
  // pricing must follow the live Neon value, not a stale local default.
  return {
    ...state,
    settings: { ...(state.settings || {}) },
    meta: {
      ...(state.meta || {}),
      migrations: {
        ...migrations,
        [PICKLECAM_HOURLY_RATE_MIGRATION]: new Date().toISOString(),
      },
    },
  };
};
