import React, { useEffect, useState } from "react";
import toast from "react-hot-toast";
import TeamBadge from "./TeamBadge";

const LEVEL_LABELS = {
  "Newbie": "NEW",
  "Beginner": "BEG",
  "L.Inter": "L. INT",
  "H.Inter": "H. INT",
  "Advance": "ADV",
};

const LEVEL_SYMBOLS = {
  "Newbie": "⚪",   // white/grey — absolute novice
  "Beginner": "🟡", // yellow
  "L.Inter": "🟢", // green
  "H.Inter": "🔵", // blue
  "Advance": "🟣", // purple
};

const LEVEL_OPTIONS = ["Newbie", "Beginner", "L.Inter", "H.Inter", "Advance"];




export default function PlayerRow({
  player,
  rowNumber,
  queued,
  onRemovePlayer,
  onUpdateLevel,
  onUpdateGender,
  onStopPlayer,
  onResumePlayer,
  onDepartPlayer,
  onAddToQueue,
  onRenamePlayer,
  isDuplicate,
  isRequested,
  partnerInfo,
  recentMatchColor,
  teamBadge,
}) {
  const [waitMs, setWaitMs] = useState(0);
  const [editingName, setEditingName] = useState(false);
  const [tempName, setTempName] = useState(player.name);
  const [departConfirm, setDepartConfirm] = useState(false);

  useEffect(() => {
    if (!editingName) setTempName(player.name);
  }, [player.name, editingName]);

  useEffect(() => {
    const active = player.status === "waiting" || player.status === "queued";
    if (!active) {
      setWaitMs(0);
      return;
    }
    const update = () => {
      if (player.waitStart) {
        const elapsed = Math.max(0, Date.now() - player.waitStart);
        setWaitMs(elapsed);
      }
    };
    update();
    const id = setInterval(update, 1000);
    return () => clearInterval(id);
  }, [player.status, player.waitStart]);

  const formattedWait = (() => {
    const totalSeconds = Math.floor(waitMs / 1000);
    const minutes = Math.floor(totalSeconds / 60)
      .toString()
      .padStart(2, "0");
    const seconds = (totalSeconds % 60).toString().padStart(2, "0");
    return `${minutes}:${seconds}`;
  })();

  const statusClasses =
    player.status === "waiting"
      ? "bg-green-100 text-green-700"
      : player.status === "playing"
        ? "bg-blue-100 text-blue-700"
        : player.status === "queued"
          ? "bg-amber-100 text-amber-700"
          : player.status === "stopped"
            ? "bg-orange-100 text-orange-700"
            : player.status === "departed"
              ? "bg-red-100 text-red-700"
              : "bg-gray-200 text-gray-700";

  const canQueue = player.status === "waiting" && !queued && !isRequested;

  // Partner availability check for queue button
  const partnerBlocked = partnerInfo?.isActive && partnerInfo?.partnerStatus !== "waiting";

  const handleQueueClick = () => {
    if (partnerBlocked) {
      toast.error(`Cannot queue: Partner ${partnerInfo.partnerName} is ${partnerInfo.partnerStatus}`, {
        duration: 4000,
        icon: "👥"
      });
      return;
    }
    // If partner is waiting, add both to queue
    if (partnerInfo?.isActive && partnerInfo?.partnerStatus === "waiting") {
      onAddToQueue(player.id, partnerInfo.partnerId);
      toast.success(`Added ${player.name} with partner ${partnerInfo.partnerName}`, { icon: "👥" });
    } else {
      onAddToQueue(player.id);
    }
  };

  // Row Classes for Duplicates
  const rowClasses = isDuplicate ? "hover:bg-red-50 bg-red-50/50" : "hover:bg-gray-50";

  // Name Cell Classes for Gender/Duplicate
  const nameCellClasses = `border p-2 ${isDuplicate
    ? "border-red-300 bg-red-100 text-red-700 font-bold"
    : player.gender === 'F'
      ? "border-pink-200 bg-pink-50 text-pink-900"
      : ""
    }`;

  // No longer used as a row-level style — color goes on the number badge instead.

  return (
    <tr className={rowClasses}>
      <td className="p-2 text-center select-none tabular-nums w-8">
        {recentMatchColor ? (
          <span
            className="inline-flex items-center justify-center rounded-full text-white font-bold text-[10px] w-5 h-5"
            style={{ background: recentMatchColor }}
          >
            {rowNumber}
          </span>
        ) : (
          <span className="text-xs text-slate-400 font-medium">{rowNumber}</span>
        )}
      </td>
      <td className={nameCellClasses}>
        {editingName ? (
          <input
            className="bg-transparent border-b border-dashed border-gray-300 focus:border-[#1E3A8A] focus:outline-none px-1 py-0.5 text-sm w-48"
            value={tempName}
            autoFocus
            onChange={(e) => setTempName(e.target.value)}
            onBlur={() => {
              const value = tempName.trim();
              if (!value) {
                setEditingName(false);
                setTempName(player.name);
                return;
              }
              if (value.toUpperCase() !== player.name) onRenamePlayer?.(player.id, value);
              setEditingName(false);
            }}
            onKeyDown={(e) => {
              if (e.key === "Enter") e.currentTarget.blur();
              if (e.key === "Escape") {
                setEditingName(false);
                setTempName(player.name);
              }
            }}
          />
        ) : (
          <div className="flex items-center gap-2">
            <button
              type="button"
              className="text-red-500 hover:text-red-700 text-xs"
              title="Remove player"
              onClick={() => onRemovePlayer(player.id)}
            >
              ×
            </button>
            {teamBadge && (
              <TeamBadge letter={teamBadge.letter} color={teamBadge.color} title={teamBadge.title} />
            )}
            <span className={isDuplicate ? "font-bold" : "font-medium"}>{player.name}</span>
            {partnerInfo?.isActive && (
              <span
                className="cursor-help"
                title={`Partner: ${partnerInfo.partnerName}`}
              >
                👥
              </span>
            )}
            {isDuplicate && <span className="text-[10px] bg-red-200 text-red-800 px-1 rounded ml-1">DUPLICATE</span>}
            <button
              type="button"
              className="text-gray-400 hover:text-[#1E3A8A] text-xs"
              title="Edit name"
              onClick={() => {
                setTempName(player.name);
                setEditingName(true);
              }}
            >
              ✎
            </button>
          </div>
        )}
      </td>

      <td className="border p-2 text-center">
        <div className="flex items-center justify-center gap-2">
          <select
            value={player.level || "Intermediate"}
            onChange={(e) => onUpdateLevel(player.id, e.target.value)}
            className="border rounded px-2 py-1 text-sm bg-white"
          >
            {LEVEL_OPTIONS.map((level) => (
              <option key={level} value={level}>
                {LEVEL_SYMBOLS[level] || "🔵"} {LEVEL_LABELS[level] || level}
              </option>
            ))}
          </select>
        </div>
      </td>

      <td className="border p-2 text-center">
        <div className="flex items-center justify-center border border-slate-200 rounded-lg overflow-hidden text-xs font-bold w-fit mx-auto">
          <button
            type="button"
            onClick={() => onUpdateGender(player.id, "M")}
            className={`px-2 py-1 transition-colors ${(player.gender || "M") === "M"
              ? "bg-blue-500 text-white"
              : "bg-white text-slate-400 hover:bg-slate-50"
              }`}
          >
            M
          </button>
          <button
            type="button"
            onClick={() => onUpdateGender(player.id, "F")}
            className={`px-2 py-1 transition-colors ${player.gender === "F"
              ? "bg-pink-500 text-white"
              : "bg-white text-slate-400 hover:bg-slate-50"
              }`}
          >
            F
          </button>
        </div>
      </td>

      <td className="border p-2 text-center">
        <span className={`px-2 py-1 rounded text-xs font-medium ${statusClasses}`}>
          {player.status}
        </span>
      </td>

      <td className="border p-2 text-center">{formattedWait}</td>

      <td className="border p-2 text-center">{player.matches}</td>

      <td className="border p-2 text-center space-x-1">
        {/* Pause / Resume */}
        {player.status === "stopped" || player.status === "departed" ? (
          <button
            className="text-green-600 hover:text-green-800 text-base"
            onClick={() => onResumePlayer(player.id)}
            title="Resume player"
            aria-label="Resume player"
          >
            ▶
          </button>
        ) : (
          <button
            className="text-amber-600 hover:text-amber-800 text-base"
            onClick={() => onStopPlayer(player.id)}
            title="Pause player"
            aria-label="Pause player"
          >
            ⏸
          </button>
        )}

        {/* Depart — only show when player has not yet departed */}
        {player.status !== "departed" && (
          <>
            <span className="text-gray-300 select-none">|</span>
            <span className="relative inline-block">
              <button
                className="text-red-500 hover:text-red-700 text-sm font-bold px-1"
                onClick={() => setDepartConfirm(true)}
                title="Mark player as departed (went home)"
                aria-label="Depart player"
              >
                &#9209;
              </button>

              {/* Inline confirmation pop-over */}
              {departConfirm && (
                <div className="absolute right-0 bottom-7 z-50 bg-white border border-red-200 rounded-xl shadow-lg px-3 py-2 text-left w-44">
                  <p className="text-[11px] font-semibold text-slate-700 mb-1">
                    {player.name} left?
                  </p>
                  <p className="text-[10px] text-slate-500 mb-2">
                    This records departure time.
                  </p>
                  <div className="flex gap-1.5">
                    <button
                      className="flex-1 px-2 py-1 text-[10px] font-bold rounded-lg bg-red-500 text-white hover:bg-red-600"
                      onClick={() => {
                        setDepartConfirm(false);
                        onDepartPlayer?.(player.id);
                      }}
                    >
                      Yes, depart
                    </button>
                    <button
                      className="flex-1 px-2 py-1 text-[10px] font-medium rounded-lg bg-slate-100 text-slate-600 hover:bg-slate-200"
                      onClick={() => setDepartConfirm(false)}
                    >
                      Cancel
                    </button>
                  </div>
                </div>
              )}
            </span>
          </>
        )}

        <span className="text-gray-300 select-none">|</span>

        {canQueue && !partnerBlocked ? (
          <button
            className="text-[#1E3A8A] hover:text-[#243c90] text-sm"
            onClick={handleQueueClick}
            title="Add to queue"
          >
            Queue
          </button>
        ) : partnerBlocked && canQueue ? (
          <button
            className="text-amber-500 hover:text-amber-600 text-sm"
            onClick={handleQueueClick}
            title={`Partner ${partnerInfo?.partnerName} is ${partnerInfo?.partnerStatus}`}
          >
            Queue
          </button>
        ) : (
          <span className="text-gray-400 text-sm cursor-not-allowed">Queue</span>
        )}
      </td>
    </tr>
  );
}
